package com.example.location.processor; import com.example.location.model.LocationRequest; import org.apache.camel.*; import org.springframework.stereotype.Component; @Component public class EnrichStateFromCRP11X1Processor implements Processor{ public void process(Exchange ex){ LocationRequest r=ex.getMessage().getBody(LocationRequest.class); boolean hasCode=is(r.stateOrProvinceCode), hasAbbr=is(r.postalStateAbbreviation), hasCountry=is(r.countryCode); boolean needs=!(hasCode&&hasAbbr&&hasCountry)&&(hasCode||hasAbbr); ex.getMessage().setHeader("call.crp11x1", needs); ex.getMessage().setHeader("crp11x1.byCode", hasCode); } boolean is(String s){return s!=null&&!s.isBlank();} }